/**
 * One clay scene per product, 03/11/2026, generated by Paul from the briefs in
 * his product image prompts. The same two characters run through all of them
 * and through `/pricing`, so the pages read as one series.
 *
 * Where each goes is decided by what the page already has. The three pages with
 * a plain summary card get the scene in the hero, above the card. The EU Fit
 * Check and the Fit Report already carry charts in their heroes, so their scene
 * takes the "how it works" frame, which they had left empty.
 *
 * Decorative (`alt=""`): the headline and the steps beside each picture carry
 * the meaning, and a description would be new copy for the language system to
 * hold in two languages for no reader's benefit.
 *
 * Shared with `/products`, whose catalogue cards open with the same scene, so a
 * reader who taps a card lands on a picture they have already seen.
 */
export const PRODUCT_PHOTO: Record<string, { src: string; w: number; h: number; where: "hero" | "how" }> = {
  "eu-fit-check": { src: "/products/product-eu-fit-check.jpg", w: 1200, h: 896, where: "how" },
  "cv-check": { src: "/products/product-cv-check.jpg", w: 1200, h: 896, where: "hero" },
  "fit-report": { src: "/pricing/pricing-fit-report-interview.jpg", w: 1024, h: 1024, where: "how" },
  "matched-jobs": { src: "/products/product-matched-jobs.jpg", w: 1200, h: 896, where: "hero" },
  "guided-job-hunt": { src: "/products/product-guided-job-hunt.jpg", w: 1200, h: 896, where: "hero" },
};
